@Override
  protected void pullEntity(Entity target) {
    Entity owner = this.getOwner();
    if (owner != null) {
      // if requested, collect the targeted item
      // include arrows directly for modded arrow compat
      boolean collectable = target.getType().is(TinkerTags.EntityTypes.COLLECTABLES) || target instanceof ItemEntity || target instanceof AbstractArrow;
      if (collectable && isCollecting()) {
        if (owner instanceof Player player) {
          target.playerTouch(player);
          // if removed, we are done here
          if (target.isRemoved()) {
            return;
            // if not removed but it's on the list to discard on failed pickup, discard and als be done
          } else if (target.getType().is(TinkerTags.EntityTypes.DISCARDABLE_COLLECTABLES)) {
            target.discard();
            return;
          }
        }
      }

      // don't damage anything thats a collectable, mainly affects items
      if (power > 0 && !collectable) {
        // mark target hurt
        if (owner instanceof LivingEntity living) {
          living.setLastHurtMob(target);
        }
        float damage = getDamage();
        DamageSource source = CombatHelper.damageSource(TinkerEffects.needsEnderferenceOverride(target) ? TinkerDamageTypes.MELEE_FISHING_HOOK : TinkerDamageTypes.FISHING_HOOK, this, owner);
        LivingEntity targetLiving = ToolAttackUtil.getLivingEntity(target);
        // don't want to apply default knockback, we will apply our own later in the opposite direction
        AttributeInstance knockback = ToolAttackUtil.disableKnockback(targetLiving);
        // actually hurt the entity
        float oldHealth = targetLiving != null ? targetLiving.getHealth() : 0;
        if (target.hurt(source, damage)) {
          if (!this.level().isClientSide && owner instanceof LivingEntity ownerLiving) {
            if (targetLiving != null) {
              EnchantmentHelper.doPostHurtEffects(targetLiving, owner);
            }

            // run modifier hook
            modifierHook: {
              // find out which stack was used
              ItemStack stack = ownerLiving.getMainHandItem();
              if (!stack.canPerformAction(ToolActions.FISHING_ROD_CAST)) {
                stack = ownerLiving.getOffhandItem();
                if (!stack.canPerformAction(ToolActions.FISHING_ROD_CAST)) {
                  break modifierHook;
                }
              }
              // if it's a modifiable item, run the hook
              if (stack.is(TinkerTags.Items.MODIFIABLE)) {
                // calculate how much damage we actually did
                float damageDealt = damage;
                if (targetLiving != null) {
                  damageDealt = oldHealth - targetLiving.getHealth();
                }
                // actually run the hook
                IToolStackView tool = ToolStack.from(stack);
                for (ModifierEntry modifier : tool.getModifiers()) {
                  modifier.getHook(ModifierHooks.LAUNCHER_HIT).onLauncherHitEntity(tool, modifier, this, ownerLiving, target, targetLiving, damageDealt);
                }
              }
            }
          }
        }
        ToolAttackUtil.enableKnockback(knockback);
      }
      // pull the target, bonus pulling if we have punch
      Vec3 knockback = new Vec3(owner.getX() - this.getX(), owner.getY() - this.getY(), owner.getZ() - this.getZ());
      float scale = 0.1f;
      if (this.knockback > 0) {
        // use the normalized distance for the punch bonus, keep the original 0.1 as scale of total for vanilla consistency
        scale += this.knockback * 0.25f * Mth.invSqrt(knockback.lengthSqr());
      }
      target.setDeltaMovement(target.getDeltaMovement().add(knockback.scale(scale)));

      // if still alive and drill attack, we shoot towards them
      if (isDrill()) {
        pullGrapple(owner);
      }
    }
  }

@Override
  protected void onHitEntity(EntityHitResult result) {
    super.onHitEntity(result);
    // store the impact velocity to scale our damage later
    impactVelocity = this.getDeltaMovement().length();
    damageRod();
  }

@Override
  public float getDamage() {
    double velocity;
    if (getHookedIn() != null) {
      velocity = this.impactVelocity;
    } else {
      velocity = getDeltaMovement().length();
    }
    // round to the nearest 0.1
    // we start by multiplying by 15 to make the damage approximately 1/2 of a bow (as bows multiply velocity by 3)
    return Mth.ceil(Mth.clamp(velocity * this.power * 15, 0, Integer.MAX_VALUE)) / 10f;
  }

private void damageRod() {
    // we damage on both cast and release to prevent some cheese with some modifiers and swapping items post cast
    if (!level().isClientSide && getOwner() instanceof LivingEntity living) {
      ItemStack stack = living.getMainHandItem();
      InteractionHand hand = InteractionHand.MAIN_HAND;
      // must be able to cast
      if (!stack.canPerformAction(ToolActions.FISHING_ROD_CAST)) {
        stack = living.getOffhandItem();
        if (!stack.canPerformAction(ToolActions.FISHING_ROD_CAST)) {
          return;
        }
        hand = InteractionHand.OFF_HAND;
      }
      // must be modifiable
      if (stack.is(TinkerTags.Items.MODIFIABLE)) {
        ToolDamageUtil.damageAnimated(ToolStack.from(stack), 1, living, hand);
      }
    }
  }

@Override
  protected boolean canHitEntity(Entity target) {
    return super.canHitEntity(target) || (target.isAlive() && isCollecting() && (target.getType().is(TinkerTags.EntityTypes.COLLECTABLES) || target instanceof AbstractArrow));
  }

private void pullGrapple(Entity owner) {
    // pull the owner, bonus pulling if we have knockback
    Vec3 knockback = new Vec3(this.getX() - owner.getX(), this.getY() - owner.getY(), this.getZ() - owner.getZ());
    // goal is dividing the scale by the square root of the length, computed as the negative 4th root of the length squared to reduce sqrt calls.
    knockback = knockback.scale(GRAPPLE_STRENGTH * Math.pow(knockback.lengthSqr(), -0.25f));
    owner.push(knockback.x, knockback.y, knockback.z);
    if (isDrill() && owner instanceof Player player) {
      player.startAutoSpinAttack(20);
    }
    if (owner instanceof ServerPlayer player) {
      player.connection.send(new ClientboundSetEntityMotionPacket(player.getId(), player.getDeltaMovement()));
    }
  }

@Override
  public int retrieve(ItemStack stack) {
    Entity owner = this.getOwner();
    if (this.onGround() || wallState != null) {
      if (owner != null && isGrapple()) {
        pullGrapple(owner);
      }
      // run modifier hook
      if (owner instanceof LivingEntity living && stack.is(TinkerTags.Items.MODIFIABLE)) {
        IToolStackView tool = ToolStack.from(stack);
        BlockPos pos = blockPosition();
        for (ModifierEntry entry : tool.getModifiers()) {
          entry.getHook(ModifierHooks.LAUNCHER_HIT).onLauncherHitBlock(tool, entry, this, living, pos);
        }
      }
      // do at least 2 damage, but not more than 3, practically this should always be 2
      return Mth.clamp(super.retrieve(stack), 2, 3);
    }
    // deal 3 damage for mob hooking instead of 5
    return Math.min(super.retrieve(stack), 3);
  }

@Override
  protected void onHitBlock(BlockHitResult result) {
    super.onHitBlock(result);
    // TODO: this isn't super consistent at sticking in the walls
    if (isGrapple()) {
      this.setOnGround(true);
      this.wallState = level().getBlockState(result.getBlockPos());
      Vec3 hit = result.getLocation();
      Vec3 offset = hit.subtract(this.getX(), this.getY(), this.getZ());
      this.setDeltaMovement(offset);
      this.setPosRaw(hit.x, hit.y, hit.z);
    }
  }

private boolean shouldFall() {
    return wallState != null && level().noCollision((new AABB(position(), position())).inflate(0.06D));
  }

private void startFalling() {
    this.wallState = null;
    Vec3 velocity = this.getDeltaMovement();
    this.setDeltaMovement(velocity.multiply(this.random.nextFloat() * 0.2F, this.random.nextFloat() * 0.2F, this.random.nextFloat() * 0.2F));
    this.life = 0;
  }

@Override
  public void move(MoverType type, Vec3 pos) {
    // ignore gravity and other motions if in the wall currently
    if (type == MoverType.SELF && wallState != null) {
      if (wallState != level().getBlockState(blockPosition()) && shouldFall()) {
        startFalling();
      } else {
        return;
      }
    }
    // normal movement if not in a wall
    super.move(type, pos);
    // if someone else pushed us, reset movement
    if (type != MoverType.SELF && this.shouldFall()) {
      this.startFalling();
    }
  }

@Override
  public void tick() {
    // if in the wall, continue ticking life
    int oldLife = this.life;
    super.tick();
    if (this.wallState != null && !level().isClientSide) {
      this.life = oldLife + 1;
      if (this.life >= 1200) {
        this.discard();
      }
    }
  }

@Override
  public void addAdditionalSaveData(CompoundTag tag) {
    super.addAdditionalSaveData(tag);
    tag.putString(TAG_MATERIAL, getMaterial().toString());
  }

@Override
  public void readAdditionalSaveData(CompoundTag tag) {
    super.readAdditionalSaveData(tag);
    if (tag.contains(TAG_MATERIAL)) {
      setMaterial(Objects.requireNonNullElse(MaterialVariantId.tryParse(tag.getString(TAG_MATERIAL)), MaterialId.UNKNOWN));
    }
  }

@Override
  public InteractionResult onToolUse(IToolStackView tool, ModifierEntry modifier, Player player, InteractionHand hand, InteractionSource source) {
    // disallow casting if the main hand can cast. Only comes up if the main hand is doing left click fishing; vanilla limitations means we can't support that
    if (source != InteractionSource.ARMOR && !tool.isBroken() && tool.getHook(ToolHooks.INTERACTION).canInteract(tool, modifier.getId(), source) && (hand == InteractionHand.MAIN_HAND || !player.getMainHandItem().canPerformAction(ToolActions.FISHING_ROD_CAST))) {
      Level level = player.level();
      if (player.fishing != null) {
        ItemStack stack = player.getItemInHand(hand);
        // due to fishing rod buggy behavior, chance we end up retrieving someone else's cast, so keep this logic 1 to 1 with vanilla
        if (!level.isClientSide) {
          int damage = player.fishing.retrieve(stack);
          if (damage > 0) {
            ToolDamageUtil.damageAnimated(tool, damage, player, Util.getSlotType(hand));
            // we apply cooldown as this is a weapon, don't want to let you spam it. But only need the cooldown if something happened
            GeneralInteractionModifierHook.addCooldown(tool, player, 1);
          }
        }

        level.playSound( null, player.getX(), player.getY(), player.getZ(), SoundEvents.FISHING_BOBBER_RETRIEVE, SoundSource.NEUTRAL, 1, 0.4f / (level.getRandom().nextFloat() * 0.4f + 0.8f));
        player.gameEvent(GameEvent.ITEM_INTERACT_FINISH);
      } else {
        level.playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.FISHING_BOBBER_THROW, SoundSource.NEUTRAL, 0.5f, 0.4f / (level.getRandom().nextFloat() * 0.4f + 0.8f));
        if (!level.isClientSide) {
          float luck = ConditionalStatModifierHook.getModifiedStat(tool, player, ToolStats.SEA_LUCK);
          float lure = ConditionalStatModifierHook.getModifiedStat(tool, player, ToolStats.LURE);
          float velocity = ConditionalStatModifierHook.getModifiedStat(tool, player, ToolStats.VELOCITY);
          float inaccuracy = ModifierUtil.getInaccuracy(tool, player);
          CombatFishingHook hook = new CombatFishingHook(player, level, (int) luck, (int) lure, velocity, inaccuracy);
          hook.setPower(ConditionalStatModifierHook.getModifiedStat(tool, player, ToolStats.PROJECTILE_DAMAGE));
          // apply material for the renderer
          hook.setMaterial(tool.getMaterial(tool.getVolatileData().getInt(HOOK_MATERIAL)).getVariant());

          // copy tool data to the bobber for modifier hooks
          ModifierNBT modifiers = tool.getModifiers();
          EntityModifierCapability.getCapability(hook).setModifiers(modifiers);
          // apply grapple or drill
          if (ModifierUtil.canPerformAction(tool, TinkerToolActions.GRAPPLE_HOOK)) {
            hook.setGrapple(ModifierUtil.canPerformAction(tool, TinkerToolActions.DRILL_ATTACK) ? GrappleType.DRILL : GrappleType.DASH);
          }
          // apply collecting
          if (ModifierUtil.canPerformAction(tool, TinkerToolActions.ITEM_HOOK)) {
            hook.setCollecting();
          }

          // fetch the persistent data for the hook as modifiers may want to store data
          ModDataNBT arrowData = PersistentDataCapability.getOrWarn(hook);

          // let modifiers such as fiery and punch set properties
          for (ModifierEntry entry : modifiers.getModifiers()) {
            entry.getHook(ModifierHooks.PROJECTILE_LAUNCH).onProjectileLaunch(tool, entry, player, ItemStack.EMPTY, hook, null, arrowData, true);
          }
          level.addFreshEntity(hook);
        }

        player.awardStat(Stats.ITEM_USED.get(tool.getItem()));
        player.gameEvent(GameEvent.ITEM_INTERACT_START);
      }

      if (level.isClientSide) {
        OffhandCooldownTracker.swingHand(player, hand, false);
      }
      return InteractionResult.CONSUME;
    }
    return InteractionResult.PASS;
  }

@Override
  public void onUnequip(IToolStackView tool, ModifierEntry modifier, EquipmentChangeContext context) {
    // if actively fishing, switching to a new rod means we need to retrieve to prevent a cheese
    if (context.getEntity() instanceof Player player && player.fishing != null) {
      IToolStackView replacement = context.getReplacementTool();
      if (replacement == null || !replacement.getModifiers().equals(tool.getModifiers())) {
        player.fishing.discard();
      }
    }
  }

@Override
  public void onEquipmentChange(IToolStackView tool, ModifierEntry modifier, EquipmentChangeContext context, EquipmentSlot slotType) {
    // if the main hand changed such that it gained the ability to fish, then vanilla is going to move our fishing bobber to attach to the mainhand
    // so just retrieve it to prevent a cheese
    // there is technically an issue with us inheriting someone elses bobber, but thats just a worse version of our bobber, so not really a cheese
    if (slotType == EquipmentSlot.OFFHAND && context.getChangedSlot() == EquipmentSlot.MAINHAND && context.getEntity() instanceof Player player && player.fishing != null && !context.getOriginal().canPerformAction(ToolActions.FISHING_ROD_CAST) && context.getReplacement().canPerformAction(ToolActions.FISHING_ROD_CAST)) {
      player.fishing.discard();
    }
  }

private static void onEquipmentChange(LivingEquipmentChangeEvent event) {
    runModifierHooks(event.getEntity(), event.getSlot(), event.getFrom(), event.getTo());
  }

private static void runModifierHooks(LivingEntity entity, EquipmentSlot changedSlot, ItemStack original, ItemStack replacement) {
    EquipmentChangeContext context = new EquipmentChangeContext(entity, changedSlot, original, replacement);

    // first, fire event to notify an item was removed
    IToolStackView tool = context.getOriginalTool();
    if (tool != null && ModifierUtil.validArmorSlot(tool, changedSlot)) {
      for (ModifierEntry entry : tool.getModifierList()) {
        entry.getHook(ModifierHooks.EQUIPMENT_CHANGE).onUnequip(tool, entry, context);
      }
    }

    // next, fire event to notify an item was added
    tool = context.getReplacementTool();
    if (tool != null && ModifierUtil.validArmorSlot(tool, changedSlot)) {
      for (ModifierEntry entry : tool.getModifierList()) {
        entry.getHook(ModifierHooks.EQUIPMENT_CHANGE).onEquip(tool, entry, context);
      }
    }

    // finally, fire events on all other slots to say something changed
    for (EquipmentSlot otherSlot : EquipmentSlot.values()) {
      if (otherSlot != changedSlot) {
        tool = context.getValidTool(otherSlot);
        if (tool != null) {
          for (ModifierEntry entry : tool.getModifierList()) {
            entry.getHook(ModifierHooks.EQUIPMENT_CHANGE).onEquipmentChange(tool, entry, context, otherSlot);
          }
        }
      }
    }
    // fire event for modifiers that want to watch equipment when not equipped
    MinecraftForge.EVENT_BUS.post(new ToolEquipmentChangeEvent(context));
  }

@Nullable
  public static LivingEntity getLivingEntity(Entity entity) {
    if (entity instanceof PartEntity<?> part) {
      entity = part.getParent();
    }
    return entity instanceof LivingEntity living ? living : null;
  }

@Nullable
  public static AttributeInstance disableKnockback(@Nullable LivingEntity living) {
    if (living != null) {
      AttributeInstance instance = living.getAttribute(Attributes.KNOCKBACK_RESISTANCE);
      if (instance != null && !instance.hasModifier(ANTI_KNOCKBACK_MODIFIER)) {
        instance.addTransientModifier(ANTI_KNOCKBACK_MODIFIER);
        return instance;
      }
    }
    return null;
  }

public static void enableKnockback(@Nullable AttributeInstance instance) {
    if (instance != null) {
      instance.removeModifier(ANTI_KNOCKBACK_MODIFIER);
    }
  }

public static boolean needsEnderferenceOverride(@Nullable Entity entity) {
    return entity != null && entity.getType() == EntityType.ENDERMAN && entity instanceof LivingEntity living && living.hasEffect(enderference.get());
  }

@Override
  protected void onHitEntity(EntityHitResult result) {
    Entity target = result.getEntity();
    // apply knockback to the entity regardless of fluid type
    if (knockback > 0) {
      Vec3 vec3 = this.getDeltaMovement().multiply(1, 0, 1).normalize().scale(knockback * 0.6);
      if (vec3.lengthSqr() > 0) {
        target.push(vec3.x, 0.1, vec3.z);
      }
    }
    FluidStack fluid = getFluid();
    Level level = level();
    if (!level.isClientSide && !fluid.isEmpty()) {
      FluidEffects recipe = FluidEffectManager.INSTANCE.find(fluid.getFluid());
      if (recipe.hasEntityEffects()) {
        FluidEffectContext.Entity context = buildContext().location(result.getLocation()).target(target);
        int consumed = recipe.applyToEntity(fluid, power, context, FluidAction.EXECUTE);
        // update the stack
        if (consumed > 0) {
          updateCannonStack(context);
        }
        // shrink our internal fluid, means we get a crossbow piercing like effect if its not all used
        // discarding when empty ensures the fluid won't continue with the block effect
        // unlike blocks, failing is fine, means we just continue through to the block below the entity
        fluid.shrink(consumed);
        if (fluid.isEmpty()) {
          this.discard();
        } else {
          setFluid(fluid);
        }
      }
    }
  }

@Nullable
  private IItemHandlerModifiable getCannonInventory() {
    Level level = level();
    if (this.cannon != null && level.isLoaded(this.cannon)) {
      BlockEntity cannonBE = level.getBlockEntity(this.cannon);
      if (cannonBE != null && cannonBE.getCapability(ForgeCapabilities.ITEM_HANDLER).orElse(EmptyItemHandler.INSTANCE) instanceof IItemHandlerModifiable modifiable) {
        return modifiable;
      }
    }
    return null;
  }

private FluidEffectContext.Builder buildContext() {
    Level level = level();
    FluidEffectContext.Builder builder = FluidEffectContext.builder(level).projectile(this);
    Entity owner = getOwner();
    if (owner != null) {
      builder.user(owner);
    }
    if (this.cannon != null) {
      IItemHandler handler = getCannonInventory();
      if (handler != null) {
        builder.stack(handler.getStackInSlot(0).copy());
      }
    }
    return builder;
  }

private void updateCannonStack(FluidEffectContext context) {
    if (cannon != null) {
      IItemHandlerModifiable handler = getCannonInventory();
      if (handler != null) {
        handler.setStackInSlot(0, context.getStack());
      }
    }
  }

@Override
  public void tick() {
    super.tick();
    HitResult hitResult = ProjectileUtil.getHitResultOnMoveVector(this, this::canHitEntity);
    HitResult.Type hitType = hitResult.getType();
    if (hitType != HitResult.Type.MISS && !ForgeEventFactory.onProjectileImpact(this, hitResult)) {
      this.onHit(hitResult);
    }
    if (!this.isRemoved()) {
      this.updateRotation();
      Vec3 newLocation = position();
      Vec3 velocity = this.getDeltaMovement();
      // if we hit a block and are still alive, relocate ourself to that position so we don't skip blocks
      if (hitType == HitResult.Type.BLOCK) {
        EntityDimensions dimensions = getType().getDimensions();
        float factor = 0.01f;
        if (((BlockHitResult)hitResult).getDirection().getAxis() == Axis.Y) {
          factor += dimensions.height;
        } else {
          factor += dimensions.width / 2;
        }
        newLocation = hitResult.getLocation().add(velocity.normalize().scale(factor));
      } else {
        newLocation = newLocation.add(velocity);
      }
      velocity = velocity.scale(this.isInWater() ? entityData.get(WATER_INERTIA) : 0.99f);
      // TODO: reduce when underwater without fins
      if (!this.isNoGravity()) {
        FluidStack fluid = getFluid();
        velocity = velocity.add(0, fluid.getFluid().getFluidType().isLighterThanAir() ? 0.06 : -0.06, 0);
      }
      this.setDeltaMovement(velocity);
      this.setPos(newLocation);
    }
    // if the projectile moves above the world, delete it
    // only likely to happen for lighter than air fluids
    if (getY() > level().getMaxBuildHeight() + 64) {
      this.discard();
    }
  }

private static Stream<Direction> orderByNearest(Vec3 delta) {
    record DirectionDistance(Direction direction, double distance) {}
    return Arrays.stream(Direction.values())
                 // negated as we want the largest
                 .map(dir -> new DirectionDistance(dir, -(dir.getStepX() * delta.x + dir.getStepY() * delta.y + dir.getStepZ() * delta.z)))
                 .sorted(Comparator.comparingDouble(DirectionDistance::distance))
                 .map(DirectionDistance::direction);
  }

@Override
  protected void onHitBlock(BlockHitResult hitResult) {
    super.onHitBlock(hitResult);

    // hit the block
    // handle the fluid
    Level level = level();
    if (!level.isClientSide) {
      FluidStack fluid = getFluid();
      if (!fluid.isEmpty()) {
        FluidEffects recipe = FluidEffectManager.INSTANCE.find(fluid.getFluid());
        if (recipe.hasBlockEffects()) {
          FluidEffectContext.Block context = buildContext().block(hitResult);
          int consumed = recipe.applyToBlock(fluid, power, context, FluidAction.EXECUTE);
          boolean changed = consumed > 0;
          fluid.shrink(consumed);
          // we can continue to live if we have fluid left and we broke our block
          if (!fluid.isEmpty()) {
            // if we are going to get discarded due to being in a block, apply ourself to our neighbors
            BlockPos hit = hitResult.getBlockPos();
            if (level.getBlockState(hit).isAir()) {
              setFluid(fluid);
              return;
            }
            // if not air, this projectile will be removed, apply effect to neighbors before discarding
            Iterator<Direction> iterator = orderByNearest(getDeltaMovement()).iterator();
            while (iterator.hasNext() && !fluid.isEmpty()) {
              consumed = recipe.applyToBlock(fluid, power, context.withHitResult(Util.offset(hitResult, hit.relative(iterator.next().getOpposite()))), FluidAction.EXECUTE);
              fluid.shrink(consumed);
              changed |= consumed > 0;
            }
          }
          // update the item in the context with the stack changes
          if (changed) {
            updateCannonStack(context);
          }
        }
      }
      this.discard();
    }
  }

@Override
  protected void addAdditionalSaveData(CompoundTag nbt) {
    super.addAdditionalSaveData(nbt);
    nbt.putFloat(KEY_POWER, power);
    nbt.putFloat(KEY_KNOCKBACK, knockback);
    nbt.putFloat(KEY_WATER_INERTIA, this.entityData.get(WATER_INERTIA));
    if (cannon != null) {
      nbt.put(KEY_CANNON, NbtUtils.writeBlockPos(cannon));
    }
    FluidStack fluid = getFluid();
    if (!fluid.isEmpty()) {
      nbt.put(KEY_FLUID, fluid.writeToNBT(new CompoundTag()));
    }
  }

@Override
  protected void readAdditionalSaveData(CompoundTag nbt) {
    super.readAdditionalSaveData(nbt);
    this.power = nbt.getFloat(KEY_POWER);
    this.knockback = nbt.getFloat(KEY_KNOCKBACK);
    this.entityData.set(WATER_INERTIA, nbt.getFloat(KEY_WATER_INERTIA));
    if (nbt.contains(KEY_CANNON)) {
      this.cannon = NbtUtils.readBlockPos(nbt.getCompound(KEY_CANNON));
    } else {
      this.cannon = null;
    }
    setFluid(FluidStack.loadFluidStackFromNBT(nbt.getCompound(KEY_FLUID)));
  }

@SuppressWarnings("deprecation")
  @Deprecated
  @Override
  public void neighborChanged(BlockState state, Level level, BlockPos pos, Block block, BlockPos fromPos, boolean isMoving) {
    boolean hasSignal = level.hasNeighborSignal(pos) || level.hasNeighborSignal(pos.above());
    boolean wasTriggered = state.getValue(TRIGGERED);
    if (hasSignal && !wasTriggered) {
      level.scheduleTick(pos, this, 4);
      level.setBlock(pos, state.setValue(TRIGGERED, true), Block.UPDATE_INVISIBLE);
    } else if (!hasSignal && wasTriggered) {
      level.setBlock(pos, state.setValue(TRIGGERED, false), Block.UPDATE_INVISIBLE);
    }
  }

@Override
  public void tick(BlockState state, ServerLevel level, BlockPos pos, RandomSource random) {
    if (level.getBlockEntity(pos) instanceof FluidCannonBlockEntity cannon) {
      cannon.shoot(state, level, random);
    }
  }

public void shoot(BlockState state, ServerLevel level, RandomSource random) {
    FluidStack fluid = tank.getFluid();
    // if no fluid, just cancel out
    if (!fluid.isEmpty()) {
      FluidEffects recipe = FluidEffectManager.INSTANCE.find(fluid.getFluid());
      if (recipe.hasEffects()) {
        float power = block.getPower();
        Direction facing = state.getValue(FACING);
        BlockPos target = worldPosition.relative(facing);
        BlockState targetState = level.getBlockState(target);

        // if it has block effects, try applying to the block directly in front
        if (recipe.hasBlockEffects() && !targetState.getShape(level, target).isEmpty()) {
          // if a block is in the way, apply directly to the block
          // this saves fluid compared to the projectile for many interactions, but also means no multi-hit behavior
          BlockHitResult hit = Util.createTraceResult(target, facing.getOpposite(), false);
          ItemStack stack = itemHandler.getStack().copy();
          int consumed = recipe.applyToBlock(fluid, power, FluidEffectContext.builder(level).stack(stack).block(hit), FluidAction.EXECUTE);
          if (consumed > 0) {
            Vec3 location = hit.getLocation();
            level.sendParticles(new FluidParticleData(TinkerCommons.fluidParticle.get(), fluid), location.x(), location.y(), location.z(), 10, 0.1, 0.2, 0.1, 0.2);
            fluid.shrink(consumed);
            tank.setFluid(fluid);
            tank.onContentsChanged();
            itemHandler.setStack(stack);
            level.levelEvent(LevelEvent.PARTICLES_SHOOT, worldPosition, facing.get3DDataValue());
            return;
          }
        }


        // if we could not apply the fluid to the block, make a projectile provided its not blocked
        if (!targetState.isFaceSturdy(level, target, facing.getOpposite())) {
          // setup projectile
          int amount = Math.min(fluid.getAmount(), (int)(recipe.getAmount(fluid.getFluid()) * power));
          FluidEffectProjectile projectile = new FluidEffectProjectile(level, worldPosition, facing, new FluidStack(fluid, amount), power);

          // setup projectile target - numbers based on arrow dispenser behavior
          projectile.shoot(facing.getStepX(), facing.getStepY() + 0.1f, facing.getStepZ(), block.getVelocity(), block.getInaccuracy());

          // finally, fire the projectile
          level.addFreshEntity(projectile);
          level.playSound(null, projectile.getX(), projectile.getY(), projectile.getZ(), SoundEvents.LLAMA_SPIT, SoundSource.BLOCKS, 1.0F, 1.0F / (random.nextFloat() * 0.4F + 1.2F) + 0.5F);

          fluid.shrink(amount);
          tank.setFluid(fluid);
          tank.onContentsChanged();
          level.levelEvent(LevelEvent.PARTICLES_SHOOT, worldPosition, facing.get3DDataValue());
          return;
        }
      }
    }

    // did not run a recipe, play the sound of failure
    level.levelEvent(LevelEvent.SOUND_DISPENSER_FAIL, worldPosition, 0);
    level.gameEvent(GameEvent.BLOCK_ACTIVATE, worldPosition, GameEvent.Context.of(state));
  }

