@Override
  public float apply(FluidStack fluid, EffectLevel level, Entity context, FluidAction action) {
    float value = level.value();
    if (action.simulate()) {
      return value;
    }
    Projectile projectile = context.getProjectile();
    LivingEntity entity = context.getEntity();

    // if provided a specific damage type, use that
    DamageSource source;
    if (damageType != null) {
      if (projectile != null) {
        // endermen with enderference will cancel projectile damage, so switch to melee damage
        ResourceKey<DamageType> type = TinkerEffects.needsEnderferenceOverride(context.getLivingTarget()) ? damageType.melee : damageType.ranged;
        source = TinkerDamageTypes.source(context.getLevel().registryAccess(), type, projectile, entity);
      } else {
        source = TinkerDamageTypes.source(context.getLevel().registryAccess(), damageType.melee, entity);
      }
    } else {
      source = context.createDamageSource();
    }
    // FIXME: this would be nicer to use the BYPASS_COOLDOWN dmanage type tag instead. However, I don't think that would work with projectiles currently.
    return ToolAttackUtil.attackEntitySecondary(source, this.damage * value, context.getTarget(), context.getLivingTarget(), true) ? value : 0;
  }

@Override
  public float apply(FluidStack fluid, EffectLevel level, FluidEffectContext context, FluidAction action) {
    int count = (int)(level.value() * item.getCount());
    if (count > 0) {
      if (action.execute()) {
        ModifierUtil.dropItem(context.getLevel(), context.getLocation(), ItemHandlerHelper.copyStackWithSize(item.get(), count * item.getCount()));
      }
      return (float) count / item.getCount();
    }
    return 0;
  }

@SuppressWarnings("UnusedReturnValue")
  public static boolean attackEntitySecondary(DamageSource source, float damage, Entity target, @Nullable LivingEntity living, boolean noKnockback) {
    AttributeInstance knockbackResistance = null;
    // prevent knockback in secondary attacks, if requested
    if (noKnockback) {
      knockbackResistance = disableKnockback(living);
    }

    // hurt the target, bypassing invulnerability
    boolean hit = hurtNoInvulnerableTime(target, living, source, damage);

    // remove no knockback marker
    if (noKnockback) {
      enableKnockback(knockbackResistance);
    }

    return hit;
  }

public static boolean hurtNoInvulnerableTime(Entity target, @Nullable LivingEntity living, DamageSource source, float damage) {
    // store last damage before secondary attack
    float oldLastDamage = living == null ? 0 : living.lastHurt;

    // set hurt resistance time to 0 because we always want to deal damage in traits
    int lastInvulnerableTime = target.invulnerableTime;
    target.invulnerableTime = 0;
    boolean hit = target.hurt(source, damage);
    // reset to the old time so bows work right
    target.invulnerableTime = lastInvulnerableTime;
    // set total received damage, important for AI and stuff
    if (living != null) {
      living.lastHurt += oldLastDamage;
    }
    return hit;
  }

public static void dropItem(Level level, double x, double y, double z, ItemStack stack) {
    if (!stack.isEmpty() && !level.isClientSide) {
      ItemEntity ent = new ItemEntity(level, x, y, z, stack);
      ent.setDefaultPickUpDelay();
      RandomSource rand = level.random;
      ent.setDeltaMovement(ent.getDeltaMovement().add((rand.nextFloat() - rand.nextFloat()) * 0.1F,
                                                      rand.nextFloat() * 0.05F,
                                                      (rand.nextFloat() - rand.nextFloat()) * 0.1F));
      level.addFreshEntity(ent);
    }
  }

